const techniques=[["🎤","کنترل اضطراب و شروع مقتدرانه","با آمادگی، تنفس راحت و جمله آغازین تمرین‌شده، سخنرانی را حتی با وجود اضطراب شروع کنیم."],["🎯","ارائه کوتاه و تصمیم‌محور","برای مدیران ارشد، نتیجه اصلی را اول بگوییم؛ با یک شاهد و درخواست مشخص ادامه دهیم."],["🎙️","صدای رسا و روانی کلام","حجم صدای متناسب، شمرده‌گویی و بازیابی آرام پس از تپق را تمرین کنیم."],["⏸️","ریتم، مکث و تأکید صوتی","با تغییر سرعت، مکث هدفمند و تأکید بر واژه‌های کلیدی، پیام را شنیدنی کنیم."],["🧍","حضور حرفه‌ای و زبان بدن","با وضعیت بدنی متعادل، نگاه طبیعی و اشاره‌های هدفمند، حضور حرفه‌ای بسازیم."],["💬","پاسخ‌گویی بداهه به پرسش دشوار","پرسش را کامل بشنویم، پاسخ کوتاه و مستند بدهیم و هنگام ندانستن صادقانه پیگیری کنیم."]];
const techniqueDetails=[{"definition":"اضطراب را الزاماً حذف نمی‌کنیم؛ با تمرین تدریجی، Preparation و رفتار قابل‌کنترل، توان ارائه را بالا می‌بریم.","tips":["قبل از نوبت ارائه، بازدمی آرام و بدون فشار داشته باش و پاها را ثابت بگذار.","دو ثانیه سکوت کن، به دوربین یا مخاطب نگاه کن و سپس با جمله اولِ از پیش تمرین‌شده شروع کن.","به‌جای «نباید بترسم»، هدف اجرایی بگذار: «یک پیام واضح را منتقل می‌کنم»."],"example":"در آغاز جلسه کارکنان: [مکث کوتاه] «امروز می‌خواهم درباره یک تغییر مهم در تجربه مشتری صحبت کنم.»","pitfall":"تلاش برای حذف کامل استرس، عذرخواهی طولانی درباره اضطراب یا شروع عجولانه."},{"definition":"Executive Briefing: برای مخاطب تصمیم‌گیر، به‌جای روایت طولانی، ابتدا نتیجه و سپس مبنای آن را بگو.","tips":["Headline first: در جمله اول نتیجه، توصیه یا تصمیم موردنیاز را اعلام کن.","فقط یک داده یا شاهد قابل اتکا برای پشتیبانی بگو؛ فرضیه را جای واقعیت ننشان.","در پایان درخواست یا تصمیم مورد انتظار را دقیق و در محدوده اختیار مطرح کن."],"example":"در گزارش به مدیر منطقه: «پیشنهاد می‌کنم پشتیبان موقت تخصیص دهیم؛ چون صف پاسخ‌گویی بالا رفته است. درخواست من بررسی ظرفیت برای هفته آینده است.»","pitfall":"خواندن تاریخچه و همه جزئیات قبل از گفتن نکته اصلی."},{"definition":"Fluent Speech به معنای بی‌اشتباه‌بودن نیست؛ روانی یعنی بیان قابل‌فهم و بازیابی حرفه‌ای پس از لغزش.","tips":["پیش از جمله‌های طولانی نفس را طبیعی تنظیم کن و جمله را در واحدهای معنایی کوتاه بگو.","واژه‌های کلیدی و اعداد را با تلفظ واضح و حجم صدای مناسب اتاق بیان کن؛ فریاد نزن.","اگر تپق زدی، مکث کوتاه کن و عبارت را از آخرین نکته درست دوباره بگو؛ عذرخواهی‌های پی‌درپی نکن."],"example":"«نرخ پاسخ‌گویی... [مکث] اجازه بدهید دقیق بگویم: متوسط زمان پاسخ‌گویی کاهش داشته، اما علت هنوز در دست بررسی است.»","pitfall":"تندگویی برای پنهان‌کردن اضطراب یا وانمودکردن به بی‌نقص‌بودن."},{"definition":"Vocal Variety یعنی تغییر هدفمند Tempo، مکث و برجسته‌سازی؛ نه اجرای نمایشی یا صدای مصنوعی.","tips":["وقتی نکته مهم می‌رسد، کمی کندتر بگو و پس از آن مکث کوتاه کن.","روی یک واژه کلیدیِ هر جمله تأکید کن تا مخاطب سلسله‌مراتب پیام را بشنود.","از تغییر طبیعی ارتفاع و شدت صدا استفاده کن؛ یکنواخت و شتاب‌زده نخوان."],"example":"«موضوع اصلی، [مکث] سرعت پاسخ‌گویی است؛ نه صرفاً تعداد پرونده‌های بسته‌شده.»","pitfall":"بی‌وقفه حرف‌زدن، پُرکردن سکوت با «اِ...» یا تأکید روی همه کلمات."},{"definition":"Executive Presence در ارائه، ترکیبی از اتصال با مخاطب و رفتار بدنی قابل‌کنترل است؛ زبان بدن را نباید ذهن‌خوانی کرد.","tips":["در ارائه حضوری ایستادن متعادل و شانه‌های رها را حفظ کن؛ در جلسه آنلاین دوربین هم‌سطح چشم باشد.","نگاه را طبیعی بین افراد یا دوربین تقسیم کن و به‌جای خواندن متن کامل، از کلیدواژه‌ها کمک بگیر.","حرکت دست را برای توضیح نمودار یا تفکیک نکات استفاده کن؛ حرکت اضافه نکن."],"example":"هنگام نمایش نمودار عملکرد، یک لحظه به اسلاید اشاره کن، سپس رو به مخاطب بایست و نتیجه را بگو.","pitfall":"خواندن از روی اسلاید، نگاه دائم به گوشی یا تعبیر قطعی حالت بدن شنونده."},{"definition":"در Q&A حرفه‌ای، مکث و پاسخ مستند از جواب سریع و حدسی ارزشمندتر است.","tips":["اجازه بده سؤال کامل شود؛ اگر پیچیده است، آن را در یک جمله بازتاب بده.","ابتدا پاسخ مستقیم و کوتاه بده، سپس شاهد معتبر یا محدودیت داده را اضافه کن.","اگر نمی‌دانی، با آرامش بگو اطلاعات قطعی در اختیار نداری و فقط مسیر پیگیری واقعی را بیان کن."],"example":"در پاسخ به مدیرعامل: «پرسش شما درباره علت رشد شکایت است. داده فعلی افزایش را نشان می‌دهد، اما علت هنوز تأیید نشده؛ پیشنهاد می‌کنم تحلیل پرونده‌ها را ارائه دهیم.»","pitfall":"دفاعی‌شدن، قطع سؤال، پرحرفی و ساختن عدد یا وعده برای حفظ ظاهر."}];
const raw=[["معاون شعبه","شروع سخنرانی در جمع کارکنان","رئیس شعبه باید برای بیست‌وپنج همکار، جلسه ماهانه را آغاز کند؛ از نگاه جمع مضطرب است.","کنترل اضطراب و شروع مقتدرانه","همه منتظر شروع جلسه‌اند؛ از کجا می‌خواهید شروع کنید؟|[نگاه به برگه، صدای لرزان] اِ... سلام... ببخشید من کمی استرس دارم...|موضوع جلسه امروز چیست؟|[تند] خب خیلی کارها داریم؛ اجازه بدید اول همه نامه‌ها را بخوانم.|می‌توانیم بدانیم نکته اصلی چیست؟|[بدون مکث] بله بله، الان می‌گم، فقط صبر کنید...","اگر آماده‌اید، شروع کنیم.|[بازدم آرام، مکث دوثانیه‌ای، نگاه به جمع] «امروز درباره یک مسئله مهم صحبت می‌کنیم: تجربه مشتری در شعبه.»|می‌خواهید از کجا آغاز کنیم؟|[صدای متعادل] «ابتدا یک نمونه واقعی را مرور می‌کنیم، سپس راهکارها را می‌شنویم.»|اگر کسی سؤالی داشت؟|[مکث و لبخند طبیعی] «بعد از توضیح کوتاه، برای پرسش‌ها زمان می‌گذاریم.»","بازدم طبیعی و سکوت کوتاه پیش از جمله اول. جمله افتتاحیه را قبل از جلسه چند بار تمرین کن. با وجود اضطراب، شروع را به تأخیر نینداز؛ تمرکز بر پیام باشد.","آغاز با مکث و صدای کنترل‌شده","تمرکز بر کنترل اضطراب و شروع مقتدرانه و رفتار شنیدنی یا دیدنی.","تفاوت اجرای اول و دوم را براساس رفتار واقعی ارزیابی کنید."],["مدیر منطقه","اولین سی ثانیه در حضور مدیران ارشد","رئیس شعبه ناگهان برای توضیح یک تغییر عملکرد در جمع مدیران ارشد فراخوانده می‌شود.","کنترل اضطراب و شروع مقتدرانه","لطفاً بفرمایید مهم‌ترین نکته شما چیست؟|[نگاه نگران] راستش انتظار نداشتم صحبت کنم؛ اِ... اجازه بدید از اول ماجرا بگم.|زمان محدودی داریم.|[با شتاب] بله، فقط باید بگم که موضوع پیچیده است.|پس پیام اصلی شما چیست؟|[لرزش و توضیح پراکنده] درواقع چند تا مسئله هست که...","در سی ثانیه نکته اصلی را بگویید.|[دو ثانیه مکث] «نکته اصلی من، ضرورت هماهنگی مسیر پاسخ‌گویی مشتریان است.»|چه نتیجه‌ای برای شعبه دارد؟|[با صدای کنترل‌شده] «بدون هماهنگی، احتمال پاسخ‌های متفاوت بیشتر می‌شود.»|پیشنهادتان چیست؟|«پیشنهاد می‌کنم مسئول هماهنگی مشترک مشخص شود؛ جزئیات را در صورت تمایل ارائه می‌کنم.»","در برابر مقام ارشد نیز قبل از شروع یک مکث کوتاه داشته باش. یک جمله آغازین آماده درباره حوزه مسئولیت خود داشته باش. اضطراب را با سرعت زیاد یا توضیح بی‌مورد پنهان نکن.","آغاز با مکث و صدای کنترل‌شده","تمرکز بر کنترل اضطراب و شروع مقتدرانه و رفتار شنیدنی یا دیدنی.","تفاوت اجرای اول و دوم را براساس رفتار واقعی ارزیابی کنید."],["مدیرعامل","گزارش نودثانیه‌ای عملکرد شعبه","مدیرعامل تنها نود ثانیه برای شنیدن یک نکته از گزارش دوره‌ای شعبه دارد.","ارائه کوتاه و تصمیم‌محور","نود ثانیه وقت داریم؛ وضعیت شعبه چیست؟|ما از ابتدای فصل تلاش زیادی کردیم؛ ابتدا تاریخچه شرایط را توضیح می‌دهم.|مهم‌ترین نتیجه را بفرمایید.|هم تعداد مراجعه مهم است هم فروش و خسارت، و چندین عامل دیگر...|بالاخره چه تصمیمی لازم است؟|اگر اجازه بدهید اول همه جدول‌ها را مرور کنم.","لطفاً جمع‌بندی را بگویید.|«پیشنهاد اصلی من بازآرایی شیفت پاسخ‌گویی در ساعت اوج مراجعه است.»|بر چه مبنایی؟|«ثبت مراجعات ما نشان می‌دهد تراکم در ساعت‌های مشخص بیشتر است؛ این داده باید با ظرفیت کارکنان تطبیق داده شود.»|چه چیزی از من می‌خواهید؟|«مجوز بررسی یک اجرای آزمایشی کوتاه را درخواست دارم؛ نتیجه را با شاخص زمان انتظار گزارش می‌کنیم.»","نتیجه یا توصیه را در ده ثانیه اول بگو. فقط یک شاهد معتبر و مرتبط را برجسته کن. با درخواست مشخص پایان بده، نه فهرست جزئیات.","ارائه موجز، نتیجه‌محور و پایان با درخواست","تمرکز بر ارائه کوتاه و تصمیم‌محور و رفتار شنیدنی یا دیدنی.","تفاوت اجرای اول و دوم را براساس رفتار واقعی ارزیابی کنید."],["مدیر منطقه","درخواست نیروی پشتیبان با یک پیام فشرده","در جلسه آنلاین منطقه‌ای، رئیس شعبه دو دقیقه فرصت دارد ضرورت پشتیبانی موقت را مطرح کند.","ارائه کوتاه و تصمیم‌محور","موضوع درخواست شما چیست؟|ما مسائل زیادی داریم، از سامانه تا مرخصی‌ها و مراجعه‌کنندگان...|دقیقاً چه کمکی لازم دارید؟|قبلش باید بگم همکاران چقدر زحمت کشیده‌اند.|چه تصمیمی بگیریم؟|بگذارید اسلایدهای بعدی را هم نشان بدهم.","درخواست شعبه را بفرمایید.|«درخواست من بررسی امکان اختصاص پشتیبان موقت در ساعت‌های پرتردد است.»|چرا این راه را پیشنهاد می‌کنید؟|«زیرا در بازه‌های مشخص، تعداد مراجعات از ظرفیت پاسخ‌گویی بیشتر می‌شود؛ داده‌های پشتیبان را آماده دارم.»|گام بعدی چیست؟|«در صورت موافقت، برنامه آزمایشی و شاخص سنجش نتیجه را تا جلسه بعد ارائه می‌کنم.»","پیام اصلی را قبل از اسلایدها اعلام کن. یک دلیل قابل اتکا بیاور، نه فهرست گلایه‌ها. درخواست تصمیم و گام بعد را کوتاه و قابل پیگیری بگو.","ارائه موجز، نتیجه‌محور و پایان با درخواست","تمرکز بر ارائه کوتاه و تصمیم‌محور و رفتار شنیدنی یا دیدنی.","تفاوت اجرای اول و دوم را براساس رفتار واقعی ارزیابی کنید."],["کارشناس گزارش","وقتی صدا در ارائه شاخص‌ها می‌لرزد","رئیس شعبه روی ارتباط ویدئویی باید سه شاخص عملکرد را گزارش کند؛ فشار جمع باعث لرزش صدا می‌شود.","صدای رسا و روانی کلام","لطفاً شاخص اول را توضیح بدهید.|[نفس حبس‌شده، صدای کم] شـ... شاخص... ببخشید صدام می‌لرزه.|ما صدایتان را واضح نمی‌شنویم.|[تند و یک‌نفس] شاخص‌ها رو خیلی سریع می‌خونم که وقت کم نیاریم.|کدام شاخص مهم‌تر است؟|[مکث همراه با شرمندگی] اِ... الآن یادم رفت.","اولین شاخص چیست؟|[بازدم راحت، حجم صدای مناسب] «اولین شاخص، زمان پاسخ‌گویی است.»|شاخص بعد؟|«دوم، شکایت‌های ثبت‌شده؛ [مکث] سوم، زمان تعیین تکلیف.»|کدام نیازمند توجه بیشتر است؟|«بر اساس داده این دوره، ابتدا باید زمان پاسخ‌گویی را دقیق‌تر بررسی کنیم.»","نفس را حبس نکن؛ بازدم طبیعی پیش از آغاز جمله کافی است. هر شاخص را در یک واحد معنایی کوتاه با صدای قابل شنیدن بگو. وقتی لرزش حس شد، اندکی مکث و ادامه بده؛ لازم نیست بابت آن عذرخواهی کنی.","نفس طبیعی، وضوح بیان و بازیابی تپق","تمرکز بر صدای رسا و روانی کلام و رفتار شنیدنی یا دیدنی.","تفاوت اجرای اول و دوم را براساس رفتار واقعی ارزیابی کنید."],["کارشناس ستاد","تپق در میانه ارائه رسمی","رئیس شعبه هنگام گزارش درباره یک اصطلاح تخصصی تپق می‌زند و می‌ترسد اعتبارش از بین برود.","صدای رسا و روانی کلام","منظورتان از این شاخص چیست؟|[تپق] شاخص باز... بازر... نه، ببخشید، من همیشه همین‌جا اشتباه می‌کنم.|اشکالی ندارد؛ توضیحش را بگویید.|[برافروخته] اجازه دهید دوباره از اول گزارش شروع کنم.|نیازی به شروع دوباره نیست.|[با شتاب] ببخشید ببخشید، خیلی بد شد.","لطفاً مفهوم شاخص را روشن کنید.|[تپق کوتاه، مکث] «اجازه بدهید واضح‌تر بگویم: این شاخص مدت پاسخ‌گویی به درخواست را نشان می‌دهد.»|یعنی درباره کیفیت نتیجه نیست؟|«درست است؛ درباره مدت زمان پاسخ است، نه تأیید نتیجه پرونده.»|پس ادامه بدهید.|[صدای طبیعی] «در بخش بعد، تغییرات دوره‌ای آن را می‌بینیم.»","تپق را یک لغزش عادی بدان، نه شکست ارائه. مکث کن و از آخرین عبارت معنادار ادامه بده. از عذرخواهی پی‌درپی یا تندگویی برای جبران اجتناب کن.","نفس طبیعی، وضوح بیان و بازیابی تپق","تمرکز بر صدای رسا و روانی کلام و رفتار شنیدنی یا دیدنی.","تفاوت اجرای اول و دوم را براساس رفتار واقعی ارزیابی کنید."],["معاون شعبه","گزارش یکنواخت درباره شکایت مشتریان","رئیس شعبه در جلسه مدیران منطقه گزارشی مهم می‌دهد، اما همه جملات را با آهنگ یکسان می‌خواند.","ریتم، مکث و تأکید صوتی","مهم‌ترین یافته شما چیست؟|[یکنواخت و بدون مکث] گزارش شکایات بررسی شده و چند مسئله ثبت شده است و ما برنامه پیگیری داریم.|چه چیزی مهم‌تر است؟|[همان آهنگ] همان مواردی که در اسلاید دیده می‌شود.|می‌شود روشن‌تر بگویید؟|[بی‌تغییر] بله، موارد روی نمودار هستند.","نتیجه اصلی را بیان کنید.|[با مکث] «یک موضوع بیش از بقیه اهمیت دارد: [تأکید] زمان پاسخ‌گویی.»|چرا این موضوع؟|[آرام‌تر] «چون بخش قابل توجهی از گلایه‌ها به انتظار برای پاسخ مربوط است؛ باید سوابق را دقیق بررسی کنیم.»|اقدام پیشنهادی چیست؟|[تأکید بر «آزمایشی»] «یک روش آزمایشی برای پیگیری سریع‌تر پیشنهاد می‌کنم.»","قبل از نکته مرکزی مکث کن. فقط روی واژه کلیدی جمله تأکید صوتی بگذار. سرعت و ارتفاع صدا را متناسب با انتقال معنا تغییر بده.","ریتم متعادل، مکث و برجسته‌سازی واژه","تمرکز بر ریتم، مکث و تأکید صوتی و رفتار شنیدنی یا دیدنی.","تفاوت اجرای اول و دوم را براساس رفتار واقعی ارزیابی کنید."],["مسئول روابط عمومی","ارائه شتاب‌زده در وضعیت حساس","در جلسه هماهنگی پس از افزایش مراجعات، رئیس شعبه گزارش را آن‌قدر سریع می‌گوید که پیام اصلی گم می‌شود.","ریتم، مکث و تأکید صوتی","چه تغییری باید به همکاران اعلام کنیم؟|[بسیار سریع] اول وضعیت رو می‌گم بعد همه تماس‌ها و شکایت‌ها و جابه‌جایی‌ها رو با هم جلو می‌بریم.|من نتوانستم نکته‌ها را تفکیک کنم.|[سریع‌تر] گفتم دیگه، همه موارد باید همزمان پیگیری بشه.|اول کدام بخش مهم است؟|[بدون مکث] همه‌ش مهمه.","اولویت پیام امروز چیست؟|[سرعت متعادل] «اول، آرامش در پاسخ به مراجعه‌کننده.» [مکث]|و بعد؟|«دوم، ثبت دقیق درخواست.» [مکث] «سوم، ارجاع از مسیر مصوب.»|کدام را باید به خاطر بسپاریم؟|[تأکید] «سه کلمه: آرامش، ثبت، ارجاع.»","جمله‌ها را به سه بخش قابل شنیدن تقسیم کن. میان بخش‌ها مکث واقعی بگذار؛ سرعت را زیاد نکن. روی واژه‌های راهنما تأکید کن، نه همه عبارت‌ها.","ریتم متعادل، مکث و برجسته‌سازی واژه","تمرکز بر ریتم، مکث و تأکید صوتی و رفتار شنیدنی یا دیدنی.","تفاوت اجرای اول و دوم را براساس رفتار واقعی ارزیابی کنید."],["مدیر منطقه","حضور پشت تریبون در همایش شعب","رئیس شعبه برای ارائه تجربه موفق در جمع رؤسا پشت تریبون ایستاده و تمام متن را از روی کاغذ می‌خواند.","حضور حرفه‌ای و زبان بدن","به حاضران خوش‌آمد بگویید.|[چشم به کاغذ و بدن منقبض] طبق بند اول متن، به استحضار می‌رساند...|ما بیشتر دوست داریم تجربه واقعی بشنویم.|[بدون نگاه به جمع] در بند دوم چنین آمده که...|نکته عملی شما چیست؟|[نگاه همچنان به کاغذ] اجازه دهید از روی متن ادامه دهم.","از تجربه شعبه بگویید.|[ایستادن متعادل، نگاه به جمع] «می‌خواهم یک تجربه کوتاه از پاسخ‌گویی به مشتری را با شما به اشتراک بگذارم.»|مهم‌ترین درس چه بود؟|[اشاره محدود با دست] «اینکه یک پیام مشخص، رفت‌وبرگشت مشتری را کمتر می‌کند؛ البته نتیجه باید اندازه‌گیری شود.»|چه چیزی به همکاران پیشنهاد می‌دهید؟|[نگاه طبیعی به چند بخش جمع] «بیایید یک روش قابل سنجش را در شعب خود امتحان کنیم.»","با وضعیت بدنی متعادل بایست و تنش غیرضروری را رها کن. از یادداشت کلیدواژه‌ای استفاده کن، نه قرائت کامل متن. نگاه را طبیعی در جمع پخش کن و اشاره‌ها را محدود و معنادار نگه دار.","نگاه، جهت بدن و اشاره‌های معنادار","تمرکز بر حضور حرفه‌ای و زبان بدن و رفتار شنیدنی یا دیدنی.","تفاوت اجرای اول و دوم را براساس رفتار واقعی ارزیابی کنید."],["مدیر ستاد","ارائه آنلاین با دوربین و اسلاید","رئیس شعبه در یک جلسه آنلاین منطقه‌ای گزارشی ارائه می‌کند؛ دوربین پایین است و مدام پشت اسلاید پنهان می‌شود.","حضور حرفه‌ای و زبان بدن","لطفاً پیام اصلی اسلاید را بگویید.|[دوربین پایین، نگاه به صفحه] همان چیزی که در اسلاید نوشته، همه می‌توانند بخوانند.|می‌توانید جمع‌بندی کنید؟|[هنوز چشم به پایین] تمام نکات همین‌جاست.|پیشنهاد شما چیست؟|[بی‌ارتباط با دوربین] مورد بعدی را باز می‌کنم.","مهم‌ترین برداشت از اسلاید چیست؟|[دوربین هم‌سطح چشم] «این نمودار نشان می‌دهد کجا باید بیشتر بررسی کنیم.»|کدام بخش؟|[نگاه کوتاه به نمودار و بازگشت به دوربین] «این بازه زمانی که در آن مراجعات بیشتر بوده است.»|اقدام بعدی؟|[حالت بدن متعادل] «پیشنهاد می‌کنم علت را بررسی و نتیجه را در نشست بعد گزارش کنیم.»","دوربین را در صورت امکان نزدیک به ارتفاع چشم تنظیم کن. به‌جای خواندن اسلاید، برداشت شفاهی خود را بیان کن. نگاه بین نمودار و دوربین جابه‌جا شود؛ حرکت بدن طبیعی باشد.","نگاه، جهت بدن و اشاره‌های معنادار","تمرکز بر حضور حرفه‌ای و زبان بدن و رفتار شنیدنی یا دیدنی.","تفاوت اجرای اول و دوم را براساس رفتار واقعی ارزیابی کنید."],["مدیرعامل","پاسخ به پرسش انتقادی مدیرعامل","پس از ارائه کوتاه، مدیرعامل می‌پرسد چرا شکایت‌ها بیشتر شده‌اند؛ رئیس شعبه هنوز علت قطعی ندارد.","پاسخ‌گویی بداهه به پرسش دشوار","چرا تعداد شکایت‌ها افزایش پیدا کرده؟|[قطع صحبت] نه، موضوع این نیست، ما همه تلاش‌مون رو کردیم!|من درباره علت می‌پرسم.|[دفاعی] همکاران کم‌اند؛ همه می‌دونن علت همینه.|آیا تحلیل مستند دارید؟|[با شتاب] حتماً، مطمئنم همین علت اصلیه.","چرا شکایت‌ها افزایش پیدا کرده‌اند؟|[مکث کوتاه] «پرسش شما درباره علت افزایش است؛ درست متوجه شدم؟»|بله، علت دقیق را می‌خواهم.|«افزایش ثبت‌شده است، اما علت قطعی هنوز از داده‌ها تأیید نشده.»|پس چه اقدامی می‌کنید؟|«پیشنهاد می‌کنم پرونده‌های مربوط را دسته‌بندی و تحلیل کنیم و نتیجه را در گزارش تکمیلی ارائه دهیم.»","سؤال را کامل بشنو و در صورت نیاز بازتاب بده. پاسخ مستقیم بده؛ داده تأییدنشده را قطعی معرفی نکن. با لحن غیردفاعی، اقدام تکمیلی قابل انجام را پیشنهاد کن.","مکث پیش از پاسخ و لحن غیردفاعی","تمرکز بر پاسخ‌گویی بداهه به پرسش دشوار و رفتار شنیدنی یا دیدنی.","تفاوت اجرای اول و دوم را براساس رفتار واقعی ارزیابی کنید."],["مدیر منطقه","وقتی پاسخ سؤال مقام ارشد را نمی‌دانیم","در پایان ارائه، مدیر منطقه درباره یک عدد دقیق می‌پرسد که رئیس شعبه بدون دسترسی به گزارش نمی‌تواند تأیید کند.","پاسخ‌گویی بداهه به پرسش دشوار","تعداد دقیق پرونده‌های معوق هفته گذشته چند مورد بوده؟|[دستپاچه] فکر کنم حدوداً... اِ... الان دقیق یادم نیست، شاید هم بیشتر.|این عدد قابل استناد است؟|[با تردید] بله احتمالاً؛ ولی شاید هم نه.|پس گزارش را براساس چه عددی بنویسم؟|[سریع] همان عدد را بزنید، بعد درست می‌کنیم.","عدد دقیق پرونده‌های معوق چقدر بوده؟|[مکث و صدای متعادل] «عدد دقیق را بدون گزارش تأیید نمی‌کنم.»|پس چطور تصمیم بگیریم؟|«نسخه ثبت‌شده را با مسئول گزارش تطبیق می‌دهم تا مبنای تصمیم درست باشد.»|زمان مشخص دارید؟|«در حال حاضر موعد تأییدشده‌ای ندارم؛ پس از بررسی، زمان معتبر اطلاع‌رسانی را اعلام می‌کنم.»","تحت فشار هم با مکث کوتاه کنترل گفتار را حفظ کن. صریح بگو کدام داده را نمی‌توانی تأیید کنی. قول زمان یا عدد ساختگی نده؛ مسیر واقعی پیگیری را پیشنهاد کن.","مکث پیش از پاسخ و لحن غیردفاعی","تمرکز بر پاسخ‌گویی بداهه به پرسش دشوار و رفتار شنیدنی یا دیدنی.","تفاوت اجرای اول و دوم را براساس رفتار واقعی ارزیابی کنید."]];
